-- Ginnie Springs
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'ginnie-springs',
    'Ginnie Springs',
    'spring',
    'private',
    29.83608,
    -82.70015,
    'deep',
    true,
    'no',
    'Mon-Thu 8 a.m.-5 p.m.; Fri-Sat 8 a.m.-7 p.m.; Sun 8 a.m.-6 p.m. Day passes stop being issued at 3 p.m. and expire at sunset. Divers register by 5 p.m. (4 p.m. in winter).',
    'Day admission: adults $25 (Mar-Oct) or $20 (Nov-Feb); children 4-12 $6 or $5; age 3 and under free. Certified divers $36; full-cave divers $28. Tubes $10 single / $20 double per day; snorkel mask or fins $8 each; life jackets free.',
    false,
    'https://ginniespringsoutdoors.com/plan-your-visit/admission-pricing/',
    '{"alcohol":"Open containers only inside campsites (policy effective Apr 21, 2026). Prohibited at the springs, decks, swimming areas, bathhouses and picnic areas. No glass bottles anywhere on the property.","tubing":"Float the Santa Fe River from Beaver''s Landing to Twin Spring (about 1 hour), then a 15-minute walk back. Free air-fill station.","pets":"No pets allowed.","life_jackets":"Free of charge; not required.","other":["Every guest signs a waiver.","Visitors under 16 need constant adult supervision; campers under 18 need a guardian.","Snorkelers on the river must tow a dive flag or float (state law).","No solo diving; divers must register and sign the dive waiver."]}'::jsonb,
    '02322400',
    '02322500',
    2,
    '{"gridId":"JAX","gridX":28,"gridY":39,"forecast":"https://api.weather.gov/gridpoints/JAX/28,39/forecast","forecastHourly":"https://api.weather.gov/gridpoints/JAX/28,39/forecast/hourly"}'::jsonb,
    'FLZ035',
    'FLC041',
    null,
    true,
    'No lifeguards on duty - swim at your own risk. The water is about 72 F year-round. Ginnie''s springs open into the Devil''s cave system: cave diving is only for certified cave divers, and open-water divers may not carry lights or enter any overhead environment (an iron grate closes the Ginnie Ballroom cavern after past diver deaths). Santa Fe River currents can be strong and the water dark after rain.',
    'https://ginniespringsoutdoors.com/',
    '/photos/ginnie-springs.jpg',
    'Private park at 5000 NE 60th Ave, High Springs (386-454-7188). Day passes can be bought online - encouraged but not required. Admissions are limited under the park''s safety policy and late arrivals are not guaranteed entry; day guests park in overflow lots on busy summer weekends. Third-party reports say it rarely sells out, so no typical fill time is listed.',
    null,
    'A privately run springs park on the Santa Fe River with several clear blue spring pools, sun decks and stairs with railings into the water. Popular with snorkelers, tubers and cave divers; it charges per person rather than per car.'
)
