-- Poe Springs Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'poe-springs-park',
    'Poe Springs Park',
    'spring',
    'county',
    29.82583,
    -82.64928,
    'deep',
    true,
    'unknown',
    'Open 7 days. May-Sep 8 a.m.-8 p.m.; Oct-Mar 8 a.m.-5 p.m. (April hours are not published). The spring and boat ramp close 30 minutes before the park. Closed Thanksgiving, Christmas and New Year''s Day.',
    'May-Sep: $6 per vehicle, or $1 per person for walk-ins and cyclists. Oct-Mar: free.',
    false,
    null,
    '{"alcohol":"Not stated on the county page - ask at the gate.","tubing":"Tube rentals on the river through the park concessionaire (Anderson''s Outdoor Adventures).","pets":"Allowed on a hand-held leash at all times; pets may not swim in the spring.","life_jackets":"Not stated on the county page.","other":["The park may close when the spring reaches its capacity of 100 people.","Scuba diving is not permitted."]}'::jsonb,
    null,
    '02321975',
    4.9,
    '{"gridId":"JAX","gridX":30,"gridY":39,"forecast":"https://api.weather.gov/gridpoints/JAX/30,39/forecast","forecastHourly":"https://api.weather.gov/gridpoints/JAX/30,39/forecast/hourly"}'::jsonb,
    'FLZ236',
    'FLC001',
    '11:00',
    false,
    'No lifeguard statement is published - assume no lifeguard on duty. Spring water is about 72 F. The spring pool opens onto the Santa Fe River, which runs high, fast and murky after heavy rain; the swim area closes whenever water clarity is poor. Entry is by concrete steps with a handrail.',
    'https://alachuacounty.us/Depts/Parks/Pages/Details.aspx?park=Poe+Springs+Park',
    '/photos/poe-springs-park.jpg',
    'Alachua County park at 28800 NW 182nd Ave, High Springs (352-264-6847). No reservations. The designated swim area has been closed since Jul 16, 2026 (poor water clarity; the spring stopped flowing during the 2026 drought); picnic areas, trails, the boat launch and paddling remain open. With only 100 people allowed in the spring it can fill late morning on summer weekends when open.',
    null,
    'A small Alachua County park where a spring pool meets the Santa Fe River, with a lodge, pavilions and a boardwalk through cypress swamp. Cheaper and quieter than the state parks, but the swim area closes whenever the river backs up or clarity drops.'
)
