-- ---------------------------------------------------------------- accessibility (deep tier)
delete from public.accessibility where park_id in (select id from public.parks where slug in ('ichetucknee-springs-state-park', 'ginnie-springs', 'poe-springs-park', 'gilchrist-blue-springs-state-park', 'rainbow-springs-state-park', 'blue-spring-state-park', 'wekiwa-springs-state-park'));
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 'limited', 'other', null, null, true, 'paved', null, true, null, 'Head Spring: one staff/volunteer-assisted chair lift plus a staircase with handrails; stairs may be slippery. Blue Hole: staircase with handrails, deep with strong current (strong swimmers only). Dampier''s Landing (tubing): 0.25-mile paved trail and ramp to the water''s edge, rocky sloped entry. South Takeout: paved ramp and concrete stairway with handrails in the water; wheelchair-accessible tram carries wheelchairs to the takeout.', 'Service animals are not allowed in the swimming areas or on tubes (official).', true, 'Official accessible-features page (all restrooms have at least one ADA stall; wheelchair-accessible picnic pads; no ADA parking count or loaner chair published).');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'ginnie-springs'), 'unknown', 'stairs', null, null, null, 'boardwalk', null, true, null, 'Each spring has sun decks and sturdy stairs with railings into the water (facilities page). No statement about wheelchair water entry.', 'No pets allowed; the park publishes no service-animal statement.', false, 'Inferred from ginniespringsoutdoors.com facilities page - no ADA parking, accessible-restroom or wheelchair statements (the site''s /accessibility/ page is a website WCAG statement, not park access).');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'poe-springs-park'), 'unknown', 'unknown', null, null, null, 'unknown', null, null, null, 'Not published. (Photos show concrete steps with a handrail into the spring pool - unverified.)', 'Not published; county ADA coordinator: ADA@alachuacounty.us, 352-374-5275.', false, 'Alachua County park page lists pavilions, restrooms, boardwalk, boat launch and an ADA coordinator contact only - no on-site accessibility details.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'gilchrist-blue-springs-state-park'), 'unknown', 'unknown', null, null, null, 'unknown', null, null, null, 'Not published. Swim entrance, launch and bathrooms are being rebuilt (no water activities since Oct 29, 2025); a third-party summary says the renovation includes an ADA path to the springhead - unverified. Port-o-lets only until renovations finish.', 'Service animals are welcome (official accessible-amenities list).', false, 'Official experiences-amenities page lists accessible concession, picnic facilities and campsites only - no water-entry, ADA parking or restroom statements.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 'unknown', 'unknown', null, null, null, 'paved', true, null, null, 'Swim area is 10-18 ft deep with no shallow end. The park does not describe how wheelchair users enter the water. Pathways were built before ADA guidelines and are steep and uneven in places (brick, concrete and asphalt).', 'Pets are not permitted in swimming areas; no separate service-animal statement on the park page (system policy excludes service animals from swimming areas).', true, 'Official experiences-amenities page: a wheelchair is available in the gift shop first-come, first-served (driver''s licence deposit); campground has ADA restrooms; headsprings restroom accessibility and ADA parking count not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'blue-spring-state-park'), 'unknown', 'unknown', null, null, true, 'boardwalk', null, null, null, 'An accessible boardwalk leads to the spring (official). The park does not describe the swim-dock entry (stairs/ramp/lift) for wheelchair users. Boat tours have a wheelchair lift into the vessel.', 'Pets including service animals are prohibited on the water (official).', true, 'Official experiences-amenities page: accessible boardwalk to Blue Spring, two bathhouses with accessible showers and stalls, accessible picnic pavilions, cabins and campsites; water-entry method, ADA parking count and loaner chairs not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 'yes', 'ramp', null, null, null, 'unknown', null, null, null, 'Ramp for spring entry plus a hydraulic swim lift rated to 400 lb, usable alone or with a companion (tell park staff at entry if you want help). The seat can stay in the water until you are ready to get out. Swim area is shallow: under 1 ft to about 5 ft. Two accessible restrooms with showers are in the campground; spring-area restroom accessibility is not stated.', 'Service animals are welcome in all areas of the park except swimming areas (official).', true, 'Official experiences-amenities page, ''Accessible Amenities'': chair lift for spring entry, ramp for spring entry, four accessible campsites; ADA nature center and boardwalk trail.');

-- ---------------------------------------------------------------- parking_lots (curated)
delete from public.parking_lots where source = 'curated' and park_id in (select id from public.parks where slug in ('ichetucknee-springs-state-park', 'ginnie-springs', 'poe-springs-park', 'gilchrist-blue-springs-state-park', 'rainbow-springs-state-park', 'blue-spring-state-park', 'wekiwa-springs-state-park'));
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 'North Entrance lot (Head Spring & Blue Hole swimming)', 29.9838, -82.7598, 'Included in park entry ($6 per vehicle)', null, null, false, 'curated', 'Approximate location near 8294 SW Elim Church Rd. Often reaches capacity on hot summer weekends and holidays, at which time the gate temporarily closes. No roadside waiting - law enforcement issues citations. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 'South Entrance lot (Dampier''s Landing tubing)', 29.95557, -82.77201, 'Included in park entry ($6 per vehicle)', null, null, false, 'curated', 'OSM parking way 174751914 near 12087 SW US Hwy 27. Tubing only - no swimming from this entrance. Fills early on summer weekends; wheelchair-accessible tram runs to the takeout. No roadside waiting - citations issued.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'ginnie-springs'), 'Main lot at Ginnie Spring', 29.83563, -82.70033, 'Included in per-person admission', null, null, false, 'curated', 'OSM parking way 583713771. General parking is available at each spring location (facilities page). ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'ginnie-springs'), 'Day-guest overflow lots', 29.8335, -82.6992, 'Included in per-person admission', null, null, true, 'curated', 'Approximate location near the entrance road. Day guests are directed to overflow lots on busy summer weekends; expect a walk to the springs.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'poe-springs-park'), 'Main lot near the spring and lodge', 29.8262, -82.6498, '$6 per vehicle May-Sep; free Oct-Mar', null, null, false, 'curated', 'Approximate location near 28800 NW 182nd Ave. Spring capacity is 100 people, so the park can close before the lot is full. Swim area closed since Jul 16, 2026. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'gilchrist-blue-springs-state-park'), 'Main day-use lot', 29.8288, -82.6846, 'Included in park entry ($6 per vehicle)', null, null, false, 'curated', 'Approximate location near 7450 NE 60th St. On busy weekends the gate closes at capacity and day visitors are not readmitted until the next morning (visitor reports). Lot layout may change with the current renovations. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 'Headsprings (swimming) entrance lot', 29.10513, -82.43883, 'Included in park entry ($5 per vehicle); day-use reservation required', null, null, false, 'curated', 'OSM parking way 457781954 near 19158 SW 81st Place Rd. Under renovation Sep 9, 2026 - Feb 4, 2027 with limited parking. When the headsprings reach capacity the park closes and vehicles may not wait in line on adjacent roads. News reports cite roughly 250 vehicles per day (estimate). ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 'Tubing entrance lot (seasonal)', 29.0782, -82.4331, 'Included in park entry; tube/shuttle fees extra', null, null, false, 'curated', 'Approximate location near 10830 SW 180th Ave Rd. Separate entrance for tubing only - no swimming. Open daily Memorial Day-Labor Day, weekends in spring and September, closed Oct-Mar.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'blue-spring-state-park'), 'Main day-use lot (swim area & concession)', 28.94441, -81.33797, 'Included in park entry ($6 per vehicle); day-use reservation required', null, null, false, 'curated', 'OSM parking way 229078670. Park frequently reaches capacity and may close for several hours; campers and boat-tour guests are still admitted. News reports cite about 232 vehicle slots per day (estimate). ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'blue-spring-state-park'), 'Second day-use lot (picnic area)', 28.9425, -81.34039, 'Included in park entry ($6 per vehicle); day-use reservation required', null, null, true, 'curated', 'OSM parking way 229078671 (access=yes, surface lot). Approximate role - used once the main lot fills.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 'Main spring lot (picnic area & swim lawn)', 28.7118, -81.4622, 'Included in park entry ($6 per vehicle, paid online with the reservation)', null, null, false, 'curated', 'Approximate location west of the spring lawn, near 1800 Wekiwa Circle. Entry is by day-use reservation only, so the lot rarely overflows but reservations sell out on hot weekends. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 'Overflow lot along the park drive', 28.7108, -81.4642, 'Included in park entry', null, null, true, 'curated', 'Approximate location. Grass/overflow parking opened by rangers on peak days; longer walk to the spring.');

-- ---------------------------------------------------------------- park_alerts (manual)
delete from public.park_alerts where source = 'manual' and park_id in (select id from public.parks where slug in ('gilchrist-blue-springs-state-park', 'poe-springs-park', 'ichetucknee-springs-state-park', 'rainbow-springs-state-park', 'wekiwa-springs-state-park'));
insert into public.park_alerts ("park_id", "kind", "text", "source", "official_url", "severity", "starts_at", "ends_at", "hash", "first_seen", "last_seen", "active", "last_checked_at")
values ((select id from public.parks where slug = 'gilchrist-blue-springs-state-park'), 'closure', 'Effective Oct. 29, 2025: Due to construction renovations, there are no water activities available at Ruth B. Kirby Gilchrist Blue Springs State Park. The large pavilion, large picnic area and volleyball courts are open; port-o-let facilities are in place until renovations are complete. Rentals and concession services are also unavailable. No reopening date has been announced.', 'manual', 'https://www.floridastateparks.org/learn/construction-renovations-ruth-b-kirby-gilchrist-blue-springs-state-park', 'Severe', '2025-10-29T00:00:00-04:00'::timestamptz, null, '59e9149d2f98694b82679765f3183e64d9dbcdba', now(), now(), true, now())
on conflict ("hash") do update set "text" = excluded."text", "official_url" = excluded."official_url", "severity" = excluded."severity", "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at", "active" = excluded."active", "last_seen" = now(), "last_checked_at" = now();
insert into public.park_alerts ("park_id", "kind", "text", "source", "official_url", "severity", "starts_at", "ends_at", "hash", "first_seen", "last_seen", "active", "last_checked_at")
values ((select id from public.parks where slug = 'poe-springs-park'), 'closure', 'Effective Thursday, July 16, 2026: The designated swimming area at Poe Springs Park is temporarily closed due to poor water clarity, and is reassessed weekly. The rest of the park (picnic areas, trails, boat launch and paddling) remains open. In August 2026 the Florida Springs Institute reported that the spring had stopped flowing during drought; no reopening timeline has been given.', 'manual', 'https://alachuacounty.us/Depts/Parks/Pages/Details.aspx?park=Poe+Springs+Park', 'Severe', '2026-07-16T00:00:00-04:00'::timestamptz, null, '0f571fbf066d52163828bb2e9cd3621d65cc2f1f', now(), now(), true, now())
on conflict ("hash") do update set "text" = excluded."text", "official_url" = excluded."official_url", "severity" = excluded."severity", "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at", "active" = excluded."active", "last_seen" = now(), "last_checked_at" = now();
