values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 'notice', 'Effective Sept. 9, 2026: The parking lot at Rainbow Springs State Park will undergo renovations from Sept. 9, 2026 to Feb. 4, 2027. Limited parking will be available; the park may reach capacity earlier than usual.', 'manual', 'https://www.floridastateparks.org/parks-and-trails/rainbow-springs-state-park', 'Moderate', '2026-09-09T00:00:00-04:00'::timestamptz, '2027-02-04T23:59:59-05:00'::timestamptz, '8f293e3edbfaa3def5074146714e918adbd97134', now(), now(), true, now())
